-- AlterTable: a review photo can also be a static site file (e.g. /reviews/x.webp) instead of an uploaded one
ALTER TABLE "Testimonial" ADD COLUMN "photoUrl" TEXT;

-- Seed the three reviews that used to be built into the site so they can be edited or removed in Admin -> Testimonials
INSERT INTO "Testimonial" ("id", "kind", "quote", "name", "role", "rating", "photoUrl", "isActive", "sortOrder", "createdAt", "updatedAt") VALUES
  ('seed-review-akash', 'TEXT', $q$Satyendra Kushwaha Sir is an exceptional mentor who has transformed my trading knowledge, discipline, patience, and mindset. His honest, practical guidance makes complex concepts easy to understand and helps me grow both as a trader and as a person. I’m truly grateful to have him as my mentor and highly recommend him to anyone serious about learning trading the right way. 🙏🏼❤️$q$, 'Akash Wagadre', 'Mumbai, India', 5, '/reviews/akash-wagadre.webp', true, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  ('seed-review-ganesan', 'TEXT', $q$My 2–3 years of trading struggle and fear completely changed after following Satyendra Kushwaha Sir. His mindset, sniper entries, trade trailing, stop-loss placement, and risk-reward management have transformed my trading journey. His biggest quality is that he shares his valuable knowledge completely free, teaching genuinely from the heart. Today, I have gained confidence, improved my understanding, and started seeing consistent, profitable results. Thank you so much, Sir, for your priceless guidance. Hats off to you! May God bless you always. 🙏🏼❤️$q$, 'Ganesan Gounder', 'Pune, India', 5, '/reviews/ganesan-gounder.webp', true, 2, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  ('seed-review-prince', 'TEXT', $q$I wanted to properly thank you for everything you’ve taught me. The accuracy of your levels still amazes me. Price reacts exactly where you mark it, and it has changed the way I read charts. The biggest thing I’ve learned from you is discipline: respecting the stop loss, taking only good risk-to-reward trades, and trailing to full target instead of closing early out of fear. You made me actually follow these, not just know them. Your calm mindset inspires me. And you teach all of this for free, without hiding anything, which is very rare in this market. Thank you, Sir. I’m truly grateful to have you as my mentor 🙏❤️$q$, 'Prince Pal', 'Gurugram, India', 5, '/reviews/prince-pal.webp', true, 3, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT ("id") DO NOTHING;
